import { cva, type VariantProps } from "class-variance-authority"
import { cn } from "@/lib/utils"

/**
 * What state an object is in: a square dot and a word.
 * Only `issue` (filled triangle) and `opportunity` (outlined diamond) use the signal colour. Never the shape alone.
 */
const stateTagVariants = cva("inline-flex items-center gap-1.5 text-[13px] leading-[19px] before:size-[7px] before:shrink-0 before:content-['']", {
  variants: {
    state: {
      watching: "text-muted-foreground before:bg-current",
      issue: "text-signal before:bg-current before:[clip-path:polygon(50%_0,100%_100%,0_100%)] before:size-2",
      opportunity: "text-foreground before:size-2 before:rotate-45 before:shadow-[inset_0_0_0_1.5px_var(--gc-accent)]",
      investigating: "text-foreground before:bg-current before:animate-pulse",
      resolved: "text-muted-foreground before:shadow-[inset_0_0_0_1.5px_currentColor]",
    },
  },
  defaultVariants: { state: "watching" },
})

const LABEL = { watching: "Watching", issue: "Issue", opportunity: "Opportunity", investigating: "Investigating", resolved: "Resolved" } as const

export interface StateTagProps extends VariantProps<typeof stateTagVariants> {
  /** Overrides the default word, e.g. "+14% power". */
  children?: React.ReactNode
  className?: string
}

export function StateTag({ state = "watching", children, className }: StateTagProps) {
  return (
    <span data-slot="state-tag" data-state={state} className={cn(stateTagVariants({ state }), className)}>
      {children ?? LABEL[state ?? "watching"]}
    </span>
  )
}
